      „basePath”: ”https://example.com/api'„,
      „processResponse”: „body”
    }
  },
  „jsonscript”: {
    „logLevel”: „info”
  },
  „processResponse”: „myExecutor.processResponse”,
  „Promise”: function() {
    // Definiția personalizată a promisiunii
  }
}

