        "featureReduction": {
          "type": "selection"
        }
      }
    },
    {
      "type": "Feature",
      "geometry": {
        "type": "Point",
        "coordinates": [-122.4192, 37.7751]
      },
      "properties": {
        "name": "Point 2",
        "featureReduction": {
          "type": "selection"
        }
